package pl.patentstart;

import android.content.Context;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.*;
import java.security.spec.X509EncodedKeySpec;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.regex.*;

public final class UpdateManager {
 public interface Listener {void event(String name,String value);}
 private static final String[] OFFICIAL={"api.sejm.gov.pl","eli.gov.pl","www.pzss.org.pl","csp.edu.pl","saami.org","czubstrapiwebsitestorage.blob.core.windows.net"};
 private static boolean running=false;
 public static byte[] read(InputStream in,int max)throws IOException{if(in==null)throw new IOException("Brak pliku");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[16384];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>max)throw new IOException("Plik przekracza limit");out.write(b,0,n);}return out.toByteArray();}
 static JSONObject jsonAsset(Context c,String name)throws Exception{try(InputStream in=c.getAssets().open(name)){return new JSONObject(new String(read(in,2*1024*1024),StandardCharsets.UTF_8));}}
 public static synchronized JSONObject bank(Context c)throws Exception{File f=new File(c.getFilesDir(),"bank.json");if(f.exists())try(InputStream in=new FileInputStream(f)){JSONObject stored=new JSONObject(new String(read(in,2*1024*1024),StandardCharsets.UTF_8));JSONObject bundled=jsonAsset(c,"bank.json");return stored.getInt("version")>=bundled.getInt("version")?stored:bundled;}return jsonAsset(c,"bank.json");}
 public static JSONObject status(Context c){JSONObject s;try{s=new JSONObject(c.getSharedPreferences("updates",0).getString("status","{}"));}catch(Exception e){s=new JSONObject();}try{if(!s.has("sources"))s.put("sources",new JSONObject());s.put("feed",feed(c));s.put("running",running);}catch(Exception ignored){}return s;}
 static String feed(Context c){String configured=c.getSharedPreferences("updates",0).getString("feed",null);if(configured!=null)return configured;try{return jsonAsset(c,"config.json").optString("feed","");}catch(Exception e){return "";}}
 public static void setFeed(Context c,String value){if(!value.isEmpty())validateHttps(value);c.getSharedPreferences("updates",0).edit().putString("feed",value).apply();}
 static void validateHttps(String value){try{URL u=new URL(value);String h=u.getHost().toLowerCase(Locale.ROOT);if(!u.getProtocol().equals("https")||u.getUserInfo()!=null||h.isEmpty()||h.equals("localhost")||h.endsWith(".local")||h.matches("[0-9.]+")||h.contains(":"))throw new Exception();}catch(Exception e){throw new IllegalArgumentException("Nieprawidłowy adres HTTPS");}}
 static byte[] download(String value,boolean official)throws Exception{validateHttps(value);URL u=new URL(value);for(int i=0;i<5;i++){
   if(official&&!Arrays.asList(OFFICIAL).contains(u.getHost()))throw new IOException("Nieoficjalna domena");
   HttpURLConnection conn=(HttpURLConnection)u.openConnection();conn.setConnectTimeout(15000);conn.setReadTimeout(25000);conn.setInstanceFollowRedirects(false);conn.setRequestProperty("User-Agent","PatentStart/1.0 (source-verification)");try{int code=conn.getResponseCode();if(code>=300&&code<400){String location=conn.getHeaderField("Location");if(location==null)throw new IOException();u=new URL(u,location);validateHttps(u.toString());continue;}if(code!=200)throw new IOException("HTTP "+code);try(InputStream in=conn.getInputStream()){return read(in,24*1024*1024);}}finally{conn.disconnect();}
  }throw new IOException("Za dużo przekierowań");}
 static String sha(byte[] bytes)throws Exception{byte[] hash=MessageDigest.getInstance("SHA-256").digest(bytes);StringBuilder s=new StringBuilder();for(byte b:hash)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static String fingerprint(JSONObject source,byte[] bytes)throws Exception{String kind=source.getString("kind");String scope=source.optString("scope","");if(!scope.isEmpty()){if(!scope.equals("html-main-v1")||!kind.equals("sha256")||!new URL(source.getString("url")).getHost().equals("saami.org"))throw new IOException("Nieobsługiwany zakres kontroli");return sha(SourceFingerprint.htmlMain(bytes));}if(kind.equals("meta"))return new JSONObject(new String(bytes,StandardCharsets.UTF_8)).getString("changeDate");if(kind.equals("links")){Matcher matcher=Pattern.compile("href\\s*=\\s*['\"]([^'\"]+\\.(?:pdf|docx?)(?:\\?[^'\"]*)?)['\"]",Pattern.CASE_INSENSITIVE).matcher(new String(bytes,StandardCharsets.UTF_8));TreeSet<String> links=new TreeSet<>();while(matcher.find())links.add(matcher.group(1).replace("&amp;","&").trim());if(links.isEmpty())throw new IOException("Brak dokumentów w wykazie");return sha(String.join("\n",links).getBytes(StandardCharsets.UTF_8));}return sha(bytes);}
 static void notify(Listener l,String name,String value){if(l!=null)l.event(name,value);}
 public static void check(Context context,Listener listener){final Context c=context.getApplicationContext();synchronized(UpdateManager.class){if(running){notify(listener,"onNativeStatus",status(c).toString());return;}running=true;}notify(listener,"onNativeStatus",status(c).toString());JSONObject s=status(c);try{
   String feed=feed(c);if(!feed.isEmpty())try{String pack=new String(download(feed,false),StandardCharsets.UTF_8);JSONObject envelope=new JSONObject(pack);byte[] payload=Base64.decode(envelope.getString("payload"),Base64.DEFAULT);JSONObject proposed=new JSONObject(new String(payload,StandardCharsets.UTF_8));if(proposed.optInt("version")>bank(c).getInt("version")){install(c,pack);notify(listener,"onBankUpdated","");s=status(c);}s.remove("feedError");}catch(Exception e){s.put("feedError","Nie udało się pobrać lub zweryfikować aktualizacji.");notify(listener,"onNativeMessage","Kanał aktualizacji jest niedostępny lub pakiet jest nieprawidłowy.");}
   JSONObject b=bank(c);JSONArray sources=b.getJSONArray("sources");JSONObject states=s.optJSONObject("sources");if(states==null)states=new JSONObject();long now=System.currentTimeMillis();
   for(int i=0;i<sources.length();i++){JSONObject src=sources.getJSONObject(i);String id=src.getString("id");JSONObject previous=states.optJSONObject(id),ss=previous==null?new JSONObject():new JSONObject(previous.toString());try{byte[] bytes=download(src.getString("url"),true);String fingerprint=fingerprint(src,bytes);boolean changed=!fingerprint.equals(src.getString("fingerprint"));ss.put("checkedAt",now);ss.put("changed",changed);ss.put("error",false);if(!changed)ss.put("lastMatchedAt",now);}catch(Exception e){ss.put("error",true);ss.put("attemptAt",now);}states.put(id,ss);s.put("sources",states);c.getSharedPreferences("updates",0).edit().putString("status",s.toString()).apply();notify(listener,"onNativeStatus",s.toString());}
   s.put("lastCheck",now);
  }catch(Exception e){notify(listener,"onNativeMessage","Nie udało się sprawdzić źródeł. Spróbuj ponownie z dostępem do internetu.");}finally{synchronized(UpdateManager.class){running=false;}try{s.put("running",false);}catch(Exception ignored){}c.getSharedPreferences("updates",0).edit().putString("status",s.toString()).apply();notify(listener,"onNativeStatus",status(c).toString());}
 }
 static void validateBank(JSONObject b)throws Exception{
  if(b.getInt("schema")!=1||b.getInt("version")<1)throw new Exception("Nieobsługiwana wersja");
  SimpleDateFormat format=new SimpleDateFormat("yyyy-MM-dd",Locale.ROOT);format.setLenient(false);Date released=format.parse(b.getString("releaseDate")),until=format.parse(b.getString("reviewUntil"));long now=System.currentTimeMillis();if(released==null||until==null||released.getTime()>now+86400000L||until.before(released)||until.getTime()-released.getTime()>92*86400000L)throw new Exception("Nieprawidłowe daty pakietu");
  JSONArray categories=b.getJSONArray("categories");if(categories.length()!=5)throw new Exception("Nieprawidłowe działy");
  JSONObject exam=b.getJSONObject("exam");if(exam.getInt("minutes")<1||exam.getInt("minutes")>120||exam.getInt("perCategory")!=2||exam.getInt("minCorrect")<1||exam.getInt("minCorrect")>10)throw new Exception("Nieprawidłowe reguły egzaminu");JSONArray critical=exam.getJSONArray("criticalCategories");for(int i=0;i<critical.length();i++)if(critical.getInt(i)<0||critical.getInt(i)>4)throw new Exception("Nieprawidłowe reguły");
  Set<String> srcIds=new HashSet<>(),ids=new HashSet<>();JSONArray sources=b.getJSONArray("sources");if(sources.length()>30)throw new Exception("Za dużo źródeł");for(int i=0;i<sources.length();i++){JSONObject s=sources.getJSONObject(i);if(!srcIds.add(s.getString("id")))throw new Exception("Powielone źródło");URL u=new URL(s.getString("url"));validateHttps(u.toString());if(!Arrays.asList(OFFICIAL).contains(u.getHost()))throw new Exception("Źródło spoza oficjalnych serwisów");if(!s.getString("kind").equals("meta")&&!s.getString("kind").equals("sha256")&&!s.getString("kind").equals("links"))throw new Exception("Nieznany typ kontroli");String scope=s.optString("scope","");if(!scope.isEmpty()&&(!scope.equals("html-main-v1")||!s.getString("kind").equals("sha256")||!u.getHost().equals("saami.org")))throw new Exception("Nieobsługiwany zakres kontroli");if(s.getString("fingerprint").isEmpty())throw new Exception("Brak odcisku źródła");}
  JSONArray qs=b.getJSONArray("questions");if(qs.length()<10||qs.length()>10000)throw new Exception("Nieprawidłowa liczba pytań");int[] counts=new int[5];for(int i=0;i<qs.length();i++){JSONObject q=qs.getJSONObject(i);if(!ids.add(q.getString("id"))||q.getInt("revision")<1)throw new Exception("Powielone pytania");int cat=q.getInt("cat");if(cat<0||cat>4)throw new Exception("Nieprawidłowy dział");counts[cat]++;JSONArray a=q.getJSONArray("answers");int correct=q.getInt("correct");if(a.length()!=3||correct<0||correct>=a.length()||q.getString("q").isEmpty()||q.getString("why").isEmpty()||q.getString("ref").isEmpty())throw new Exception("Niepełne pytanie");Set<String> options=new HashSet<>();for(int j=0;j<a.length();j++)if(a.getString(j).isEmpty()||!options.add(a.getString(j)))throw new Exception("Nieprawidłowe odpowiedzi");JSONArray deps=q.getJSONArray("sources");if(deps.length()==0)throw new Exception("Brak źródła pytania");for(int j=0;j<deps.length();j++)if(!srcIds.contains(deps.getString(j)))throw new Exception("Nieznane źródło");}
  for(int count:counts)if(count<2)throw new Exception("Niepełny zakres bazy");
 }
 public static synchronized void install(Context c,String envelope)throws Exception{
  JSONObject e=new JSONObject(envelope);byte[] payload=Base64.decode(e.getString("payload"),Base64.DEFAULT),signature=Base64.decode(e.getString("signature"),Base64.DEFAULT);if(payload.length>2*1024*1024)throw new Exception("Pakiet jest zbyt duży");byte[] key;try(InputStream in=c.getAssets().open("public-key.der")){key=read(in,4096);}Signature verifier=Signature.getInstance("SHA256withRSA");verifier.initVerify(KeyFactory.getInstance("RSA").generatePublic(new X509EncodedKeySpec(key)));verifier.update(payload);if(!verifier.verify(signature))throw new Exception("Nieprawidłowy podpis wydawcy");JSONObject next=new JSONObject(new String(payload,StandardCharsets.UTF_8));validateBank(next);JSONObject old=bank(c);if(next.getInt("version")<=old.getInt("version"))throw new Exception("Pakiet nie jest nowszy od zainstalowanego");
  Map<String,JSONObject> oldById=new HashMap<>();JSONArray oldQs=old.getJSONArray("questions");for(int i=0;i<oldQs.length();i++)oldById.put(oldQs.getJSONObject(i).getString("id"),oldQs.getJSONObject(i));JSONArray newQs=next.getJSONArray("questions");for(int i=0;i<newQs.length();i++){JSONObject q=newQs.getJSONObject(i),previous=oldById.get(q.getString("id"));if(previous!=null){if(q.getInt("revision")<previous.getInt("revision"))throw new Exception("Cofnięcie rewizji pytania");boolean different=false;for(String field:new String[]{"q","answers","correct","cat","why","ref","sources"})if(!q.get(field).toString().equals(previous.get(field).toString()))different=true;if(different&&q.getInt("revision")<=previous.getInt("revision"))throw new Exception("Zmienione pytanie wymaga nowej rewizji");}}
  File target=new File(c.getFilesDir(),"bank.json"),temp=new File(c.getFilesDir(),"bank.next");try(FileOutputStream out=new FileOutputStream(temp)){out.write(payload);out.getFD().sync();}if(!temp.renameTo(target))throw new IOException("Nie można zapisać pakietu");c.getSharedPreferences("updates",0).edit().remove("status").apply();
 }
}

